WITH matched_keys AS (SELECT customer_id, status FROM subscriptions INTERSECT SELECT customer_id, status FROM subscriptions WHERE customer_id IS NULL), verified AS (SELECT s.* FROM subscriptions s INNER JOIN matched_keys k ON s.customer_id = k.customer_id AND s.status = k.status) SELECT s.customer_id, s.plan, s.start_date, s.end_date, s.status, CASE WHEN status RLIKE '^(ACTIVE|EXPIRED)$' THEN 'OTHER_ZONE' WHEN status RLIKE '^(CANCELLED|PAUSED)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS status_zone, (SELECT SUM(t2.discount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS sum_order_discount FROM verified s ORDER BY start_date NULLS FIRST
